import { toggleNotification } from "./actions";
import { getNotificationPreference } from "./store";

export default function Home() {
  const notificationsEnabled = getNotificationPreference();

  return (
    <main>
      <h1>Settings</h1>
      <p>
        Notifications are currently:{" "}
        <strong>{notificationsEnabled ? "ON" : "OFF"}</strong>
      </p>
      <form action={toggleNotification}>
        <button type="submit">
          Turn {notificationsEnabled ? "Off" : "On"} Notifications
        </button>
      </form>
    </main>
  );
}

